sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float4 screen;
uniform float2 layer;
uniform float3x3 toLayer;
uniform float3x3 fromLayer;
uniform float3x3 acLayerToScreen;
uniform float zoom;
uniform float offset;
uniform float mirror;
uniform float vertical;
uniform float angle;
uniform float sizing;
float2 AcLayerNorm(float2 p) {
    float3 h = toLayer * float3(p, 1.0);
    return h.xy / max(layer, float2(1.0));
}
half4 main(float2 coord) {
    float2 pixelSize = 1.0 / max(layer, float2(1.0));
    float2 tiledCoord = AcLayerNorm(coord);
    if (vertical > 0.5) tiledCoord.y += step(1.0, mod(tiledCoord.x, 2.0)) * offset;
    else tiledCoord.x += step(1.0, mod(tiledCoord.y, 2.0)) * offset;
    if (mirror > 0.5) tiledCoord = abs(mod(tiledCoord - float2(1.0), float2(2.0)) - float2(1.0));
    else tiledCoord = mod(tiledCoord, float2(1.0));
    float a = radians(angle);
    float2x2 rot = float2x2(cos(a), -sin(a), sin(a), cos(a));
    float2 scaledCoord = tiledCoord - float2(0.5);
    scaledCoord *= float2(1.0) / max(float2(zoom) + pixelSize * 4.0, float2(0.0001));
    scaledCoord.x *= layer.x / max(layer.y, 1.0);
    scaledCoord *= rot;
    scaledCoord.x *= layer.y / max(layer.x, 1.0);
    scaledCoord += float2(0.5);
    float2 screenNorm = (float3(scaledCoord, 1.0) * acLayerToScreen).xy;
    return image.eval(screenNorm * screen.zw + screen.xy);
}
